from .store import RELEASED_STATE, BillingStore, refund_term


def invalidate(store: BillingStore, merchant_id=None) -> None:
    """Forget cached provider charge lists (all merchants, or one)."""
    if merchant_id is None:
        store.charge_cache = {}
        store.dirty_merchants = set()
    else:
        store.charge_cache.pop(merchant_id, None)
        store.dirty_merchants.discard(merchant_id)


def forget_failures(store: BillingStore) -> None:
    for merchant_id in [m for m, v in store.charge_cache.items() if v is None]:
        del store.charge_cache[merchant_id]


def merchant_charges(store: BillingStore, provider, merchant_id):
    """Every provider charge of a merchant account (one request, cached).

    Returns None when the provider could not be asked.
    """
    cache = store.charge_cache
    if merchant_id not in cache:
        try:
            found = provider.search_charges(merchant_id)
            cache[merchant_id] = [dict(c) for c in (found or [])]
        except Exception:
            cache[merchant_id] = None
    return cache[merchant_id]


def remember_charge(store: BillingStore, merchant_id, record: dict) -> None:
    cached = store.charge_cache.get(merchant_id)
    if cached is None:
        return
    for row in cached:
        if row.get("charge_id") == record.get("charge_id"):
            return
    cached.append(dict(record))


def split_charges(charges, invoice_id):
    """(succeeded charge records, refunded charge ids) of one invoice."""
    live, dead = [], []
    for charge in charges:
        if charge.get("invoice_id") != invoice_id:
            continue
        if charge.get("status") == "succeeded":
            live.append(charge)
        elif charge.get("status") == "refunded":
            dead.append(charge.get("charge_id"))
    return live, dead


def _oldest(live):
    def age(charge):
        created = charge.get("created_at")
        return (created is None, created if created is not None else 0, str(charge.get("charge_id")))
    try:
        return min(live, key=age)
    except TypeError:
        return live[0]


def apply_refund_term(store: BillingStore, invoice_id: str, dead_ids) -> str:
    """The invoice's payment was refunded and no succeeded charge remains."""
    row = store.invoice(invoice_id)
    store.note_refunds(invoice_id, dead_ids)
    if refund_term(row.get("merchant_id")) == "release":
        store.mark_unpaid(invoice_id, RELEASED_STATE)
        return RELEASED_STATE
    store.mark_unpaid(invoice_id, "retry")
    return "retry"


def settle_invoice(store: BillingStore, invoice_id: str, charges):
    """Align one invoice row with the provider's records. Returns the new state or None."""
    row = store.invoice(invoice_id)
    if not store.managed(row):
        return None
    live, dead = split_charges(charges, invoice_id)
    state, current = row.get("state"), row.get("charge_id")
    if live:
        if state == "paid" and any(c.get("charge_id") == current for c in live):
            return None
        store.mark_paid(invoice_id, _oldest(live)["charge_id"])
        return "paid"
    if not dead or state == "failed":
        return None
    if state == "paid" and current not in dead:
        return None
    if state == "paid" or current is not None or refund_term(row.get("merchant_id")) == "release":
        return apply_refund_term(store, invoice_id, dead)
    store.note_refunds(invoice_id, dead)
    return None


def sync_store(store: BillingStore, provider) -> list[dict]:
    """Align every invoice that has payment history with the provider's records."""
    by_merchant = {}
    for invoice_id, row in store.invoices.items():
        if store.managed(row):
            by_merchant.setdefault(row.get("merchant_id"), []).append(invoice_id)
    changes = []
    for merchant_id, invoice_ids in by_merchant.items():
        if not any(store.has_history(i) for i in invoice_ids):
            continue
        charges = merchant_charges(store, provider, merchant_id)
        if charges is None:
            continue
        for invoice_id in sorted(invoice_ids):
            new_state = settle_invoice(store, invoice_id, charges)
            if new_state:
                changes.append({"invoice_id": invoice_id, "state": new_state,
                                "charge_id": store.invoice(invoice_id).get("charge_id")})
    return changes


def reconcile_pending(store: BillingStore, provider) -> list[dict]:
    """Settle invoices from provider records (matched by invoice, succeeded charges only)."""
    forget_failures(store)
    for invoice_id in store.due():
        attempts = store.attempts_for(invoice_id)
        if attempts and attempts[-1].get("outcome") == "timeout":
            merchant_id = store.invoice(invoice_id).get("merchant_id")
            if merchant_id in store.dirty_merchants:
                invalidate(store, merchant_id)
    changes = []
    for change in sync_store(store, provider):
        if change["state"] == "paid":
            changes.append({"invoice_id": change["invoice_id"], "charge_id": change["charge_id"]})
    return changes
