        self.limited = set()
        forget_failures(self.store)

    def _view(self, invoice_id: str, outcome: str) -> dict:
        row = self.store.invoice(invoice_id)
        return {"invoice_id": invoice_id, "state": row.get("state"), "outcome": outcome,
                "charge_id": row.get("charge_id")}

    def submit(self, invoice_id: str) -> dict:
        store = self.store
        invoice = store.invoice(invoice_id)
        if invoice.get("state") == "paid":
            return {"invoice_id": invoice_id, "state": "paid", "charge_id": invoice["charge_id"]}
        if invoice.get("state") not in store.DUE_STATES or not store.managed(invoice):
            return self._view(invoice_id, "skipped")
        merchant_id = invoice.get("merchant_id")
        if merchant_id in self.limited:
            return self._view(invoice_id, "deferred")
        attempts = store.attempts_for(invoice_id)
        dead = set(store.refund_notes.get(invoice_id, ()))
        if store.has_history(invoice_id):
            # Never charge an invoice with payment history before checking what
            # the provider already holds for it.
            charges = merchant_charges(store, self.provider, merchant_id)
            if charges is None:
                return self._view(invoice_id, "deferred")
            settle_invoice(store, invoice_id, charges)
            invoice = store.invoice(invoice_id)
            if invoice.get("state") == "paid":
                return self._view(invoice_id, "reconciled")
            if invoice.get("state") not in store.DUE_STATES:
                return self._view(invoice_id, "skipped")
            dead.update(split_charges(charges, invoice_id)[1])
        for row in attempts:
            if row.get("outcome") == "succeeded" and row.get("charge_id"):
                dead.add(row.get("charge_id"))
        dead.discard(None)
        declined = sum(1 for row in attempts if row.get("outcome") == "declined")
        generation = len(dead) + declined
        attempt = store.next_attempt(invoice_id)
        key = payment_key(invoice, attempt, generation)
        charge_id = None
        try:
            result = self.provider.charge(
                key,
                merchant_id=merchant_id,
                invoice_id=invoice_id,
                subscription_id=invoice["subscription_id"],
                period=invoice["period"],
                amount=invoice["amount"],
            )
        except ProviderTimeout:
            outcome, state = "timeout", "retry"
            store.dirty_merchants.add(merchant_id)
        except ProviderError as exc:
            outcome, state = (getattr(exc, "code", None) or "provider_error"), "retry"
            if outcome == "rate_limited":
                self.limited.add(merchant_id)
        else:
            if result.get("status") == "succeeded":
                outcome, state, charge_id = "succeeded", "paid", result["charge_id"]
            else:
                outcome, state = "declined", "failed"
        store.record_attempt(invoice_id, attempt=attempt, key=key, outcome=outcome, charge_id=charge_id)
        if state == "paid":
            store.mark_paid(invoice_id, charge_id)
            remember_charge(store, merchant_id, {
                "charge_id": charge_id, "invoice_id": invoice_id, "merchant_id": merchant_id,
                "subscription_id": invoice["subscription_id"], "period": invoice["period"],
                "amount": invoice["amount"], "status": "succeeded", "refunded_at": None,
                "idempotency_key": key, "created_at": None})
