from .reconcile import apply_refund_term, invalidate, merchant_charges, settle_invoice, split_charges
from .store import BillingStore


def apply_webhook_events(store: BillingStore, events: list[dict], provider) -> int:
    """Apply provider events (charge.succeeded / charge.refunded) to invoice rows.

    Events can arrive out of order and can be stale, so each one is only a hint:
    the invoice is aligned with the provider's current charge records.
    """
    invalidate(store)
    events = list(events or [])
    refunded_ids = {e.get("charge_id") for e in events if e.get("type") == "charge.refunded"}
    applied = 0
    for event in events:
        invoice_id = event.get("invoice_id")
        if invoice_id not in store.invoices:
            continue
        applied += 1
        row = store.invoice(invoice_id)
        if not store.managed(row):
            continue
        charge_id = event.get("charge_id")
        charges = merchant_charges(store, provider, row.get("merchant_id"))
        if charges is not None:
            settle_invoice(store, invoice_id, charges)
            if any(c.get("charge_id") == charge_id for c in charges):
                continue
            row = store.invoice(invoice_id)
            if not store.managed(row) or split_charges(charges, invoice_id)[0]:
                continue
        # The provider's records do not describe this charge: fall back to the event.
        kind = event.get("type")
        if kind == "charge.succeeded":
            if row.get("state") in store.DUE_STATES and charge_id and charge_id not in refunded_ids:
                store.mark_paid(invoice_id, charge_id)
        elif kind == "charge.refunded":
            if (charge_id and row.get("charge_id") == charge_id
                    and row.get("state") in ("paid",) + tuple(store.DUE_STATES)):
                apply_refund_term(store, invoice_id, [charge_id])
    return applied
